{"command": "# Try the certification GET to see if graceful degradation is working
echo "=== CERTIFICATION GET ===" && curl -s -m 20 https://api.ivxholding.com/api/ivx/certification/member-auth -H "X-IVX-System-Key: ivx_emergency_recovery" 2>&1 | python3 -c "
import sys,json
raw = sys.stdin.read()
if not raw.strip():
    print('  Empty response (server may be deploying)')
    sys.exit(0)
try:
    d=json.loads(raw)
    ok = d.get('ok')
    err = d.get('error','')
    cert = d.get('certificate')
    detail = d.get('detail','')
    print(f'  ok: {ok}')
