        print('  >>> GRACEFUL DEGRADATION WORKING (returns null cert instead of 500) <<<')
    elif 'Internal server error' in str(err):
        print('  >>> OLD CODE STILL RUNNING (returns 500) <<<')
except Exception as e:
    print(f'  Parse error: {e}')
    print(f'  Raw ({len(raw)}b): {raw[:200]}')
""}

